import SwiftUI
@main struct SlopeMateRecorderApp:App {
    @StateObject private var recorder=Recorder()
    var body:some Scene {WindowGroup{ContentView(recorder:recorder).preferredColorScheme(.dark).onOpenURL{recorder.offerPair($0)}}}
struct ContentView:View {
    @Environment(\.scenePhase) private var phase
    @ObservedObject var recorder:Recorder
    var body:some View {NavigationStack{ScrollView{VStack(alignment:.leading,spacing:24){Text("SlopeMate Recorder").font(.largeTitle.bold());Text("Экспериментальный нативный GPS-рекордер • iOS 17+").foregroundStyle(.secondary);Text(recorder.message);Text("\(recorder.count) точек").font(.title.monospacedDigit());Button(recorder.active ? "Приостановить":"Начать / продолжить"){recorder.active ? recorder.pause():recorder.start()}.buttonStyle(.borderedProminent);Button("Завершить и сохранить"){recorder.finish()}.buttonStyle(.bordered);Button("Синхронизировать сохранённые треки"){Task{await recorder.sync()}}.disabled(!recorder.paired);ForEach(recorder.history,id:\.id){r in VStack(alignment:.leading){Text(Date(timeIntervalSince1970:r.started/1000),style:.date);Text(r.synced ? "Подтверждено сервером":r.finished ? "Ожидает синхронизации":"Не завершено").foregroundStyle(.secondary)}};Button("Отключить привязку"){recorder.forget()};Text("Запускайте запись на переднем плане. Не выгружайте рекордер принудительно. Выключенный телефон не записывает GPS. Непрерывность и расход батареи требуют испытаний на вашем iPhone.").font(.footnote).foregroundStyle(.secondary)}.padding(24)}}.onChange(of:phase){_,value in if value == .active && recorder.paired {Task{await recorder.sync()}}}.alert("Привязать рекордер?",isPresented:Binding(get:{recorder.pairingHost != nil},set:{if !$0{recorder.pairingHost=nil}})){Button("Привязать"){Task{await recorder.confirmPair()}};Button("Отмена",role:.cancel){recorder.pairingHost=nil}}message:{Text("Передать одноразовый код серверу \(recorder.pairingHost ?? "")? Привязывайте только свой аккаунт SlopeMate.")}}}
